select t.id, 1, 'Quem é José', 'leitura', 'Por que consagrar-se a São José', 'O que é consagração: entregar-se à proteção e à escola de José. Como será o caminho. · Contar à esposa que começou.', 'manual', null, null, 10, $seed${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Leitura"}]},{"type":"paragraph","content":[{"type":"text","text":"O que é consagração: entregar-se à proteção e à escola de José. Como será o caminho."}]},{"type":"paragraph","content":[{"type":"text","text":"Medite por alguns minutos: o que, na vida de São José, ilumina o seu dia de hoje como marido, pai e trabalhador? Ele não deixou palavras escritas; deixou obediência, trabalho e silêncio. É esse o modelo."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Oração"}]},{"type":"paragraph","content":[{"type":"text","text":"Pai-Nosso. Depois: \"A vós, São José, recorremos em nossa tribulação e, depois de implorar o auxílio de vossa santíssima Esposa, cheios de confiança solicitamos também o vosso patrocínio.\" Aos domingos, reze a Ladainha de São José."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ação do dia"}]},{"type":"paragraph","content":[{"type":"text","text":"Contar à esposa que começou."}]},{"type":"paragraph","content":[{"type":"text","text":"Quando terminar a ação, marque o passo como concluído. Amanhã tem mais."}]}]}$seed$::jsonb,
